    email             = EXCLUDED.email,
    handle            = EXCLUDED.handle,
    platform          = EXCLUDED.platform,
    followers         = EXCLUDED.followers,
    expected_decision = EXCLUDED.expected_decision,
    note              = EXCLUDED.note,
    labelled_at       = now();
